4. **Update any method calls and handling procedures** regarding subpartition indices.

Below is an updated code reflecting the aforementioned changes:

### ResultPartitionManager.java

```java
@Override
public ResultSubpartitionView createSubpartitionView(
        ResultPartitionID partitionId,
        int startIndex,
        int endIndex,
        BufferAvailabilityListener availabilityListener)
        throws IOException {

    final ResultSubpartitionView subpartitionView;
    synchronized (registeredPartitions) {
        final ResultPartition partition = registeredPartitions.get(partitionId);

        if (partition == null) {
            throw new PartitionNotFoundException(partitionId);
        }

        LOG.debug("Requesting subpartition range {} to {} of {}.", startIndex, endIndex, partition);

        subpartitionView = partition.createSubpartitionView(startIndex, endIndex, availabilityListener);
    }

    return subpartitionView;
}

@Override
public Optional<ResultSubpartitionView> createSubpartitionViewOrRegisterListener(
        ResultPartitionID partitionId,
        int startIndex,
        int endIndex,
        BufferAvailabilityListener availabilityListener,
        PartitionRequestListener partitionRequestListener)
        throws IOException {

    final ResultSubpartitionView subpartitionView;
    synchronized (registeredPartitions) {
        final ResultPartition partition = registeredPartitions.get(partitionId);

        if (partition == null) {
            listenerManagers
                    .computeIfAbsent(partitionId, key -> new PartitionRequestListenerManager())
                    .registerListener(partitionRequestListener);
            subpartitionView = null;
        } else {
            LOG.debug("Requesting subpartition range {} to {} of {}.", startIndex, endIndex, partition);
            subpartitionView = partition.createSubpartitionView(startIndex, endIndex, availabilityListener);
        }
    }

    return subpartitionView == null ? Optional.empty() : Optional.of(subpartitionView);
}
```

